import { createContext } from 'react';

export type MenuSubContextProps = {
  isOpen: boolean;
  setIsOpen: React.Dispatch<React.SetStateAction<boolean>>;
  isDefaultOpen: boolean;
};

export const MenuSubContext: React.Context<MenuSubContextProps> =
  createContext<MenuSubContextProps>({
    isOpen: false,
    isDefaultOpen: false,
    setIsOpen: () => null,
  });
